create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.PROBLEMMELDUNG cluster by (DAT)(
	SYSTEM_ID NUMBER(38,0) NOT NULL COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	PROBLEMMELDUNG_ID VARCHAR(50) NOT NULL COLLATE 'en-ci' COMMENT 'Eindeutieger Schlüssel zur Identifikation einer Problemmeldung.',
	BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Wenn Problemmeldung auf einem SAP Beleg basiert: Referenz zu einer SAP Belegposition (Belegart abhängig von der Belegklasse).',
	ECM_VORGANG NUMBER(18,0) NOT NULL DEFAULT 0 COMMENT 'Eindeutige Vorgangsnummer im ECM System wenn fuer das Problem eines Beleges ein Workflow gestartet wird.',
	PROBLEMCODE_ID VARCHAR(7) NOT NULL COMMENT 'Eindeutiger Fachschluessel fuer die Problemcodes;',
	ZEITSTEMPEL TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Erfassungsdatum und -uhrzeit der Problemmeldung.',
	BELEGKLASSE_ID VARCHAR(5) COLLATE 'en-ci' COMMENT 'Eindeutiger Schlueessel der Belegklassen (z. B. WB fuer Werbenbewegung)',
	URSPRUNG_BELEG_ID NUMBER(18,0) NOT NULL DEFAULT 0 COMMENT 'Nachtraeglieche Bela/Rbela referenzieren in diesem Feld die urspruengliche Eingangsrechnung, hier der Eingangsrechnungskopf.',
	URSPRUNG_BELEG_POS_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachtraeglieche Bela/Rbela referenzieren in diesem Feld die urspruengliche Eingangsrechnung, hier die Eingangsrechnungsposition.',
	URSPRUNG_BELEG_GJ NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Nachtraeglieche Bela/Rbela referenzieren in diesem Feld die urspruengliche Eingangsrechnung, hier das Eingangsrechnungsgeschaeftsjahr.',
	GP_RECH_ID VARCHAR(20) COLLATE 'en-ci' COMMENT 'Referenz zu einem externen Rechnungsbeleg  des Lieferanten, hier Rechnungsnummer.',
	GP_RECH_POS_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Referenz zu einem externen Rechnungsbeleg des Lieferanten, hier Rechnungsposition.',
	AUTO_FG NUMBER(38,0) NOT NULL COMMENT 'Kennzeichen automatische Generierung der Problemmeldung (1 = automatische Erstellung, 0 = manuelle Erstellung).',
	LOESCH_FG NUMBER(38,0) NOT NULL COMMENT 'Das Kennzeichen gibt an ob die Problemmeldung geloescht/storniert wurde. (1 = geloescht, 0 = nicht geloescht)',
	GP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Geschäftspartner - ID (Lieferanten - ID)',
	EINKAUFSORGANISATION_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT '1000=Warenlieferant 5000=Frischelieferant 9000=? könnte es auch geben.',
	ART_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Input: Artikel - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1',
	WUP_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	BETRAG_BRUTTO NUMBER(18,2) NOT NULL DEFAULT 0 COMMENT 'Bruttowert des Belegs auf dem die sich die Problemmeldung bezieht.',
	BETRAG_NETTO NUMBER(18,2) NOT NULL DEFAULT 0 COMMENT 'Nettobetrag des Beleges auf den sich die Problemmeldung bezieht.',
	BETRAG_MWST NUMBER(18,2) NOT NULL DEFAULT 0 COMMENT 'Mehrwertsteuerbetrag des Beleges auf den sich die Problemmeldung bezieht.',
	WRG_ID VARCHAR(3) NOT NULL DEFAULT 'EUR' COMMENT 'Waehrung der Betraege der Problemmeldung; Referenz zu der Tabelle wrg.',
	ERSTELLER_ID NUMBER(38,0) NOT NULL COMMENT 'Eindeutiger Schluessel fuer einen RPW User/Verursacher.',
	VERURSACHER_ID NUMBER(38,0) NOT NULL COMMENT 'Eindeutiger Schlüssel des Verursachers einer Problemmeldung (z. B. Eiinkauf).',
	ZEK_ID VARCHAR(3) NOT NULL DEFAULT '0' COMMENT 'Zentraleinkäufer - ID: Diese ID ist nicht mit der Mitarbeiter - ID identisch. So gesehen eine überflüssige ID',
	IMPRINT_NR_ORIG VARCHAR(50) NOT NULL COLLATE 'en-ci' COMMENT 'Die Imprint Nummer (entspricht einem Barcode)  identifiziert einen in dem Systemen OCR/Noterfassung erfassten Beleg eindeutig.',
	BELEG_ID_ORIG NUMBER(18,0) NOT NULL COMMENT 'Wenn Problemmeldung auf einem SAP Beleg basiert: Referenz zu einem SAP Belegkopf (Belegart abhängig von der Belegklasse).',
	BELEG_GJ_ORIG NUMBER(38,0) NOT NULL COMMENT 'Wenn Problemmeldung auf einem SAP Beleg basiert: Referenz zu dem Geschäftsjahr eines SAP Belegs (Belegart abhängig von der Belegklasse).',
	EDI_NR_ORIG NUMBER(18,0) NOT NULL COMMENT 'Wenn Problemmeldung auf einem IDOC Dokument basiert: Eindeutige IDOC Nummer zur Identifikation eines Beleges aus der EDI Schnittstelle.',
	IMPRINT_NR VARCHAR(50) NOT NULL COLLATE 'en-ci' COMMENT 'Die Imprintnummer basiert auf dem Inhalt des Attributes impnr. Ggf. wird diese Information aufgrund des Belegflusses aktualisiert und entspricht damit nicht mehr dem ursprünglichen Wert.',
	EDI_NR NUMBER(18,0) NOT NULL COMMENT 'Die edi_nr basiert auf dem Inhalt des Attributes edinum. Ggf. wird diese Information aufgrund des Belegflusses aktualisiert und entspricht damit nicht mehr dem ursprünglichen Wert.',
	BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Die beleg_id basiert auf dem Inhalt des Attributes belnr. Ggf. wird diese Information aufgrund des Belegflusses aktualisiert und entspricht damit nicht mehr dem ursprünglichen Wert. Nicht im Original vorhandene beleg_ids weden künstlich mit negativem Vorz',
	BELEG_GJ NUMBER(38,0) NOT NULL COMMENT 'Das beleg_gj basiert auf dem Inhalt des Attributes gjahr. Ggf. wird diese Information aufgrund des Belegflusses aktualisiert und entspricht damit nicht mehr dem ursprünglichen Wert.',
	DAT_ERFASST DATE NOT NULL DEFAULT CAST('1900-01-01' AS DATE) COMMENT 'Erfassungsdatum des Belegs',
	DAT_BELEG DATE NOT NULL DEFAULT CAST('1900-01-01' AS DATE) COMMENT 'Belegdatum des Ursprungsbelegs',
	DAT_BUCH DATE NOT NULL DEFAULT CAST('1900-01-01' AS DATE) COMMENT 'Buchungsdatum des Belegs',
	MANUELLE_BUCHUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Gleich 1 bei manueller Buchung',
	LAST_GP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Diese Spalte enthaelt den letzten gp (sortiert nach Zeitstempel) pro beleg_id und beleg_gj',
	PROZESSBEREICH_ID VARCHAR(10) NOT NULL COLLATE 'en-ci' COMMENT 'ID für den Prozessbereich',
	PROBLEMMELDUNG_ECM_LFD_NR NUMBER(18,0) NOT NULL DEFAULT 0 COMMENT 'Laufende Nummer der Problemmeldung aus ECM. Sap Name unbekannt',
	LAST_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag, das die letzte Problemmeldung identifiziert, wird aus Performancegründen eingeführt',
	DAT DATE NOT NULL COMMENT 'Aus Performancegründen DWH-seitig generiert aus dem zeitstempel',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_PROBLEMMELDUNG primary key (SYSTEM_ID, MANDANT_ID, PROBLEMMELDUNG_ID)
)COMMENT='RPW - Problemmeldungen aus dem RPW Umfeld aus der SAP RET Quelltabelle ZRP_SPM_PRMSG. Problemmeldungen koennen mit und ohne Bezug zu einem Beleg auftreten und ggf. verschiedene Belegarten referenzieren.'
;
